import {paginate} from './core.mjs';import {leagueFor,leagueLogoFiles} from './catalog.mjs';
const ink='#301067',cache=new Map();
export function loadImage(src){if(!cache.has(src))cache.set(src,new Promise(resolve=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>resolve(null);img.src=src;}));return cache.get(src);}
export function lines(ctx,s,max){let out=[],line='';for(const word of String(s||'—').split(/\s+/)){if(ctx.measureText(word).width>max){if(line){out.push(line);line='';}for(const ch of word){if(ctx.measureText(line+ch).width>max){out.push(line);line='';}line+=ch;}}else if(line&&ctx.measureText(line+' '+word).width>max){out.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)out.push(line);return out;}
function text(ctx,s,x,y,size=23,color=ink,width=Infinity,font='Hand'){ctx.fillStyle=color;ctx.font=`700 ${size}px ${font}`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.direction=/[\u0600-\u06ff]/.test(s)?'rtl':'ltr';const ll=Number.isFinite(width)?String(s).split('\n').flatMap(p=>lines(ctx,p,width)):String(s).split('\n');ll.forEach((l,i)=>ctx.fillText(l,x,y+(i-(ll.length-1)/2)*(size+3)));return ll.length;}
function star(ctx,x,y){ctx.fillStyle='#e91d35';ctx.beginPath();for(let i=0;i<10;i++){const a=i*Math.PI/5-Math.PI/2,r=i%2?7:17;ctx.lineTo(x+Math.cos(a)*r,y+Math.sin(a)*r);}ctx.closePath();ctx.fill();}
// The channel badge and the row that holds it must agree on how many lines the channel wraps to,
// so both prepare() and render() measure it through here rather than estimating from the text length.
const channelLines=(ctx,channel)=>{ctx.font='700 16px UI';return lines(ctx,String(channel||'—'),44).length;};
const channelBadgeHeight=n=>Math.max(34,n*19+10);
function crest(ctx,img,x,y,size){if(img){const k=Math.min(size/img.width,size/img.height);ctx.drawImage(img,x-img.width*k/2,y-img.height*k/2,img.width*k,img.height*k);}else{ctx.strokeStyle='#8d799f';ctx.lineWidth=1.5;ctx.strokeRect(x-size*.3,y-size*.35,size*.6,size*.7);text(ctx,'?',x,y,18,'#8d799f',Infinity,'UI');}}
export async function prepare(rows,catalog){await Promise.all([document.fonts.load('700 24px Hand'),document.fonts.load('700 24px UI')]);const images=new Map();const unknown=[];const urls=new Set(['assets/notebook.png',...leagueLogoFiles()]);for(const row of rows)for(const name of [row.home,row.away]){const c=catalog.find(name);if(c)urls.add(c.file);else unknown.push(name);}await Promise.all([...urls].map(async url=>images.set(url,await loadImage(url))));if(!images.get('assets/notebook.png'))throw Error('تعذر تحميل خلفية البوستر. أعد المحاولة.');for(const row of rows)for(const name of [row.home,row.away]){const c=catalog.find(name);if(c&&!images.get(c.file))unknown.push(name);}const c=document.createElement('canvas').getContext('2d');const pages=paginate(rows,r=>{c.font='700 21px Hand';const names=[[r.home,110],[r.away,108],[r.commentator,137]].map(([s,w])=>lines(c,s,w).length*24+6);return Math.max(46,...names,channelBadgeHeight(channelLines(c,r.channel))+6);});return {pages,images,unknown:[...new Set(unknown)]};}
export function render(canvas,page,date,catalog,images,index,total,config={}){canvas.width=2048;canvas.height=3072;const ctx=canvas.getContext('2d');ctx.scale(2,2);ctx.drawImage(images.get('assets/notebook.png'),0,0,1024,1536);
ctx.save();ctx.translate(525,220);ctx.rotate(-.035);const parsed=new Date(date+'T12:00:00');text(ctx,Number.isNaN(parsed.getTime())?'اختر التاريخ':new Intl.DateTimeFormat('ar-EG',{weekday:'long',day:'numeric',month:'long',numberingSystem:'latn'}).format(parsed),0,0,39,'#160829',390,'UI');ctx.restore();
ctx.save();ctx.transform(1,-.032,.018,1,0,24);text(ctx,'أهم المباريات مع المواعيد والقنوات والمعلقين',563,270,25,ink,700);let y=307;
for(const section of page){const l=leagueFor(section.league),h=section.height;ctx.fillStyle=l.color+'24';ctx.fillRect(193,y,733,40);ctx.strokeStyle=l.color+'88';ctx.lineWidth=1;ctx.strokeRect(193,y,733,h);for(const x of [300,461,812]){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x,y+h);ctx.stroke();}for(const [s,x] of [['القناة',246],['المعلق',381],['المباراة',635],['الوقت',868]])text(ctx,s,x,y+20,23,l.color);
const lim=Math.min(h-20,155);const logo=l.logo&&images.get('assets/'+l.logo+'.png');if(logo)crest(ctx,logo,123,y+lim*.37,65);else text(ctx,l.title||'⚽',123,y+30,21,l.color,115,'UI');text(ctx,l.ar,123,y+Math.max(80,lim*.74),21,l.color,126);if(h>170&&l.slogan)text(ctx,l.slogan,123,y+lim+30,17,l.color,120,'UI');let ry=y+40;
for(const {data:r,height:rh} of section.rows){const cy=ry+rh/2;if(r.featured){ctx.fillStyle='#ffed00';ctx.globalAlpha=.84;ctx.beginPath();ctx.moveTo(196,ry+3);ctx.lineTo(947,ry-1);ctx.lineTo(940,ry+rh-3);ctx.lineTo(193,ry+rh+2);ctx.closePath();ctx.fill();ctx.globalAlpha=1;star(ctx,943,cy);}ctx.strokeStyle=l.color+'40';ctx.beginPath();ctx.moveTo(193,ry+rh);ctx.lineTo(926,ry+rh);ctx.stroke();text(ctx,r.time,868,cy,25,ink,100,'UI');text(ctx,r.home,715,cy,21,ink,110);text(ctx,'×',635,cy,20,ink,Infinity,'UI');text(ctx,r.away,556,cy,21,ink,108);crest(ctx,images.get(catalog.find(r.home)?.file),791,cy,35);crest(ctx,images.get(catalog.find(r.away)?.file),483,cy,35);text(ctx,r.commentator||'—',386,cy,21,ink,137);
const bh=channelBadgeHeight(channelLines(ctx,r.channel));ctx.fillStyle='#491383';ctx.beginPath();ctx.roundRect(200,cy-bh/2,93,bh,3);ctx.fill();text(ctx,'Universe',221,cy-5,9,'white',Infinity,'UI');text(ctx,'IPTV',221,cy+8,9,'white',Infinity,'UI');text(ctx,r.channel||'—',269,cy,16,'white',44,'UI');ry+=rh;}
y+=h+20;}
ctx.restore();
// beginPath() is required: fill() does not clear the current path and restore() does not restore it,
// so without it the last channel badge's subpath is re-filled here, unskewed, over its own text.
if(config.showCta&&config.cta){ctx.fillStyle='#4b187c';ctx.beginPath();ctx.roundRect(310,1265,430,44,8);ctx.fill();text(ctx,config.cta,525,1287,18,'white',400,'UI');if(config.whatsapp)text(ctx,`واتساب: ${config.whatsapp}`,525,1325,15,ink,500,'UI');}
// Kept clear of the CTA box (y 1265-1309), which would otherwise swallow ink-coloured text.
if(total>1)text(ctx,`${index+1} / ${total}`,830,1287,18,ink,Infinity,'UI');}
